  "claims": [
    {
      "claim": "Measured human absolute oral bioavailability for the closest structural/physicochemical analogs is below the 20% threshold: sumatriptan ~14%, eluxadoline ~1%, DMT ~10-15%, and agomelatine <5%.",
      "card_ids": ["C08", "C01", "C34", "C14", "C36", "C37", "C91", "C106"]
    },
    {
      "claim": "The L3 melatonin record shows oral Cmax ~100-fold lower than IV Cmax at the same 10 mg dose, consistent with extensive first-pass/limited oral bioavailability, but Cmax alone is not an absolute F measurement.",
      "card_ids": ["C146"]
    },
    {
      "claim": "Other L3 oral exposure records involve structurally unrelated molecules (lacosamide, mirabegron, benznidazole, OSI-461, curcumin, etc.) and do not provide threshold-relevant F evidence for the query.",
      "card_ids": ["C135", "C142", "C176", "C166", "C169"]
